import { relative } from "node:path";
import { join, resolve } from "node:path";

import { DEFAULT_KEATING_CONFIG, configPath, loadKeatingConfig, writeKeatingConfig } from "../core/config.js";
import { learnerStatePath } from "../core/paths.js";
import { loadLearnerState, recordFeedback, saveLearnerState } from "../core/learner-state.js";
import {
  animateTopicArtifact,
  autoImproveArtifact,
  benchPolicyArtifact,
  promptEvalArtifact,
  currentPolicySummary,
  ensureProjectScaffold,
  evolvePolicyArtifact,
  evolvePromptArtifact,
  improveAccept,
  improveArtifact,
  improveHistory,
  improveReject,
  listArtifacts,
  mapTopicArtifact,
  planTopicArtifact,
  quizTopicArtifact,
  verifyTopicArtifact,
  timelineArtifact,
  dueTopicsArtifact,
  exportKeatingData,
  importKeatingData
} from "../core/project.js";
import type { ExportSource, FineTuneFormat } from "../core/export.js";
import type { FineTuneImportFormat } from "../core/import.js";
import { detectAiRuntime, launchShell } from "../runtime/pi.js";
import { serveWeb, type ServeWebOptions, type WebAgentRuntimeMode } from "./web.js";
import { serveWebMcp } from "../mcp/server.js";
import { color, bold, cliCommands } from "../core/theme.js";
import { printAsciiHeader } from "../core/terminal.js";
import { applySourceEdit, rollbackEdits, editResultToMarkdown } from "../core/code-edit.js";
import { KEATING_VERSION } from "../core/version.js";
import {
  addConfiguredPiPackage,
  listConfiguredPiPackages,
  recommendedPiPackagesMarkdown,
  removeConfiguredPiPackage
} from "../core/pi-packages.js";

function printUsage(): void {
  printAsciiHeader();
  console.log(bold("primary", "Keating CLI") + "  " + color.dim + color.sepia + `v${KEATING_VERSION}` + color.reset);
  console.log(color.parchment + "The Hyperteacher — cognitive empowerment through Socratic AI." + color.reset);
  console.log("");
  console.log(cliCommands());
  console.log("");
  console.log(bold("primary", "General Commands"));
  console.log(`  ${color.primary}shell${color.reset}  [initial prompt...]  Launch the AI-powered hyperteacher shell`);
  console.log(`  ${color.primary}setup${color.reset}  [--yes]             Configure Keating for this project`);
  console.log(`  ${color.primary}doctor${color.reset}                    Inspect AI runtime and renderer configuration`);
  console.log(`  ${color.primary}package${color.reset} list|add|remove|recommended  Manage extra Pi packages`);
  console.log(`  ${color.primary}web${color.reset}     [port] [--browser-only-agent|--remote|--cloud] [--root=PATH] [--no-ignore]  Start the browser UI. --root attaches the browser agent to a host project directory (defaults to $CWD). --no-ignore disables .gitignore/.ignore filtering of project files.`);
  console.log(`  ${color.primary}webmcp${color.reset}  [port] [--host=127.0.0.1]  Expose Keating tools over MCP Streamable HTTP`);
  console.log(`  ${color.primary}policy${color.reset}                    Print the active teaching policy`);
  console.log(`  ${color.primary}trace${color.reset}   [substring]        Browse debug traces and artifacts`);
  console.log("");
}

function normalizeTopLevelShellArgs(args: string[]): string[] | null {
  if (args.length === 0 || !args[0]?.startsWith("-") || args[0] === "--help" || args[0] === "-h") return null;
  return args.map((arg) => arg === "--list-model" ? "--list-models" : arg);
}

function commandUsage(command: string, example: string): Error {
  return new Error([
    `${command} needs more input.`,
    "",
    "Recover with:",
    `  ${example}`,
    "  keating help"
  ].join("\n"));
}

function unknownCommand(command: string): Error {
  return new Error([
    `Unknown command: ${command}`,
    "",
    "Recover with:",
    "  keating help",
    "  keating setup",
    "  keating shell",
    "",
    "For model discovery, use:",
    "  keating --list-models"
  ].join("\n"));
}

function optionValue(args: string[], name: string): string | undefined {
  const prefix = `${name}=`;
  const withEquals = args.find((arg) => arg.startsWith(prefix));
  if (withEquals) return withEquals.slice(prefix.length);
  const index = args.indexOf(name);
  return index >= 0 ? args[index + 1] : undefined;
}

function firstPositional(args: string[]): string | undefined {
  return args.find((arg) => !arg.startsWith("-"));
}

function firstWebPositional(args: string[]): string | undefined {
  const optionsWithValues = new Set([
    "--remote-provider",
    "--remote-endpoint",
    "--remote-region",
    "--remote-snapshot",
    "--remote-cpu",
    "--remote-memory",
    "--remote-disk",
    "--cloud-endpoint"
  ]);

  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i];
    if (!arg) continue;
    if (optionsWithValues.has(arg)) {
      i += 1;
      continue;
    }
    if (arg.startsWith("--") && arg.includes("=")) continue;
    if (!arg.startsWith("-")) return arg;
  }
  return undefined;
}

function parseWebCommand(args: string[]): { port: number; options: ServeWebOptions } {
  const modes: WebAgentRuntimeMode[] = [];
  if (args.includes("--browser-only-agent")) modes.push("browser-only");
  if (args.includes("--remote")) modes.push("remote");
  if (args.includes("--cloud")) modes.push("cloud");
  if (modes.length > 1) {
    throw new Error("Choose only one web agent mode: --browser-only-agent, --remote, or --cloud.");
  }

  const portArg = firstWebPositional(args);
  const port = portArg ? parseInt(portArg, 10) : 3000;
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    throw new Error(`Invalid port: "${portArg}". Must be an integer between 1 and 65535.`);
  }

  return {
    port,
    options: {
      agentRuntimeMode: modes[0] ?? "browser-only",
      projectRoot: optionValue(args, "--root"),
      noIgnore: args.includes("--no-ignore"),
      remoteProvider: optionValue(args, "--remote-provider"),
      remoteEndpoint: optionValue(args, "--remote-endpoint"),
      remoteRegion: optionValue(args, "--remote-region"),
      remoteSnapshot: optionValue(args, "--remote-snapshot"),
      remoteCpu: optionValue(args, "--remote-cpu"),
      remoteMemory: optionValue(args, "--remote-memory"),
      remoteDisk: optionValue(args, "--remote-disk"),
      cloudEndpoint: optionValue(args, "--cloud-endpoint")
    }
  };
}

function parseChoice<T extends string>(value: string | undefined, allowed: readonly T[], fallback: T, label: string): T {
  if (!value) return fallback;
  if ((allowed as readonly string[]).includes(value)) return value as T;
  throw new Error(`${label} must be one of: ${allowed.join(", ")}`);
}

function learnerFeedbackTopics(state: Awaited<ReturnType<typeof loadLearnerState>>): string[] {
  const covered = new Set(state.coveredTopics.map((topic) => topic.slug));
  return [...new Set(
    state.feedback
      .map((feedback) => feedback.topic.trim())
      .filter((topic) => topic && topic !== "general" && !covered.has(topic))
  )].slice(-10);
}

async function runExportCommand(cwd: string, args: string[]): Promise<void> {
  if (!args.includes("--finetune")) {
    throw new Error([
      "export needs a mode.",
      "",
      "Recover with:",
      "  keating export --finetune",
      "  keating export --finetune --source=artifacts --format=chatml",
      "",
      "Supported options:",
      "  --source=all|artifacts|sessions",
      "  --format=chatml|alpaca|both",
      "  --out=DIR",
      "  --no-redact",
      "  --min-assistant-chars=N"
    ].join("\n"));
  }

  const source = parseChoice<ExportSource>(optionValue(args, "--source"), ["all", "artifacts", "sessions"], "all", "--source");
  const format = parseChoice<FineTuneFormat>(optionValue(args, "--format"), ["chatml", "alpaca", "both"], "both", "--format");
  const minAssistantCharsValue = optionValue(args, "--min-assistant-chars");
  const minAssistantChars = minAssistantCharsValue ? Number.parseInt(minAssistantCharsValue, 10) : 80;
  if (!Number.isInteger(minAssistantChars) || minAssistantChars < 1) {
    throw new Error("--min-assistant-chars must be a positive integer.");
  }

  const result = await exportKeatingData(cwd, {
    mode: "finetune",
    source,
    format,
    outDir: optionValue(args, "--out"),
    redact: !args.includes("--no-redact"),
    minAssistantChars,
  });

  console.log(`${color.ok}Exported ${result.manifest.counts.examplesWritten} fine-tuning examples.${color.reset}`);
  console.log(relative(cwd, result.manifestPath));
  for (const file of result.manifest.files) console.log(file);
}

async function runImportCommand(cwd: string, args: string[]): Promise<void> {
  if (!args.includes("--finetune")) {
    throw new Error([
      "import needs a mode.",
      "",
      "Recover with:",
      "  keating import --finetune .keating/outputs/exports/<export-dir>",
      "  keating import --finetune train.chatml.jsonl --format=chatml",
      "",
      "Supported options:",
      "  --format=auto|chatml|alpaca",
      "  --title=TITLE"
    ].join("\n"));
  }

  const sourcePath = firstPositional(args.filter((arg) => arg !== "--finetune"));
  if (!sourcePath) {
    throw commandUsage("import", "keating import --finetune .keating/outputs/exports/<export-dir>");
  }
  const format = parseChoice<FineTuneImportFormat>(
    optionValue(args, "--format"),
    ["auto", "chatml", "alpaca"],
    "auto",
    "--format"
  );
  const result = await importKeatingData(cwd, {
    sourcePath,
    format,
    title: optionValue(args, "--title"),
  });

  console.log(`${color.ok}Imported ${result.examplesImported} fine-tune examples into ${result.sessionsImported} Keating session${result.sessionsImported === 1 ? "" : "s"}.${color.reset}`);
  for (const sessionPath of result.sessionPaths) console.log(relative(cwd, sessionPath));
  if (result.skipped > 0) console.log(`${result.skipped} skipped`);
  for (const warning of result.warnings) console.log(`${color.sepia}${warning}${color.reset}`);
}

async function runEditCommand(cwd: string, args: string[]): Promise<void> {
  const fileArg = args[0];
  if (!fileArg) {
    throw commandUsage("edit", "keating edit src/core/lesson-plan.ts");
  }

  const backupDirValue = optionValue(args, "--backup-dir");
  const backupDir = backupDirValue ? join(cwd, backupDirValue) : undefined;

  // Read edit payload from stdin if piped, otherwise expect JSON file path
  const stdinPayload = process.stdin.isTTY
    ? null
    : await new Promise<string>((resolve) => {
        let data = "";
        process.stdin.on("data", (chunk) => { data += chunk; });
        process.stdin.on("end", () => resolve(data));
      });

  if (stdinPayload) {
    const edit = JSON.parse(stdinPayload) as { search: string; replace: string; reason?: string };
    if (!edit.search || typeof edit.replace !== "string") {
      throw new Error("stdin edit must be JSON with { search: string, replace: string, reason?: string }");
    }
    const result = await applySourceEdit(cwd, {
      file: fileArg,
      search: edit.search,
      replace: edit.replace,
      reason: edit.reason || "manual edit",
    }, backupDir);
    console.log(result.success ? `${color.ok}${result.message}${color.reset}` : `${color.err}${result.message}${color.reset}`);
    if (!result.success) process.exitCode = 1;
    return;
  }

  // Interactive mode: prompt for search and replace
  console.log(`${color.sepia}Interactive edit mode for ${fileArg}${color.reset}`);
  console.log("Paste the search block, then a line with --- then the replace block.");
  console.log("End with EOF (Ctrl+D) or a line with ===");
  console.log("");

  const rl = (await import("node:readline/promises")).createInterface({ input: process.stdin, output: process.stdout });
  const lines: string[] = [];
  for await (const line of rl) {
    if (line.trim() === "===") break;
    lines.push(line);
  }
  rl.close();

  const payload = lines.join("\n");
  const separatorIndex = payload.indexOf("\n---\n");
  if (separatorIndex === -1) {
    throw new Error("Could not find separator --- between search and replace blocks.");
  }

  const search = payload.slice(0, separatorIndex);
  const replace = payload.slice(separatorIndex + 5); // skip "\n---\n"

  const result = await applySourceEdit(cwd, {
    file: fileArg,
    search,
    replace,
    reason: "interactive edit",
  }, backupDir);

  console.log(result.success ? `${color.ok}${result.message}${color.reset}` : `${color.err}${result.message}${color.reset}`);
  if (!result.success) process.exitCode = 1;
}

async function setupProject(cwd: string, args: string[]): Promise<void> {
  const yes = args.includes("--yes") || args.includes("-y");
  const existing = await loadKeatingConfig(cwd);
  let next = {
    ...DEFAULT_KEATING_CONFIG,
    ...existing,
    pi: {
      ...DEFAULT_KEATING_CONFIG.pi,
      ...existing.pi
    },
    speech: {
      ...DEFAULT_KEATING_CONFIG.speech,
      ...existing.speech
    },
    debug: {
      ...DEFAULT_KEATING_CONFIG.debug,
      ...existing.debug
    }
  };

  if (!yes && process.stdin.isTTY && process.stdout.isTTY) {
    const { runInteractiveSetup } = await import("./setup.js");
    const answers = await runInteractiveSetup({
      runtimePreference: next.pi.runtimePreference,
      defaultProvider: next.pi.defaultProvider ?? DEFAULT_KEATING_CONFIG.pi.defaultProvider ?? "openai",
      defaultModel: next.pi.defaultModel ?? DEFAULT_KEATING_CONFIG.pi.defaultModel ?? "gpt-5.5",
      defaultThinking: next.pi.defaultThinking ?? "medium"
    });

    if (!answers) {
      console.log(`${color.sepia}Setup cancelled.${color.reset}`);
      return;
    }

    next = {
      ...next,
      pi: {
        ...next.pi,
        ...answers
      }
    };
  } else {
    next = {
      ...next,
      pi: {
        ...next.pi,
        runtimePreference: DEFAULT_KEATING_CONFIG.pi.runtimePreference,
        defaultProvider: DEFAULT_KEATING_CONFIG.pi.defaultProvider,
        defaultModel: DEFAULT_KEATING_CONFIG.pi.defaultModel,
        defaultThinking: DEFAULT_KEATING_CONFIG.pi.defaultThinking
      }
    };
  }

  await writeKeatingConfig(cwd, next);
  console.log(`${color.ok}Wrote ${relative(cwd, configPath(cwd))}${color.reset}`);
  console.log(`Run ${color.primary}keating doctor${color.reset} to verify the runtime, then ${color.primary}keating shell${color.reset}.`);
}

function formatPackageList(packages: string[]): string {
  if (packages.length === 0) {
    return [
      "No extra Pi packages configured for Keating.",
      "",
      "Try:",
      "  keating package recommended",
      "  keating package add npm:pi-subagents"
    ].join("\n");
  }

  return [
    "Extra Pi packages configured for Keating:",
    ...packages.map((pkg) => `  - ${pkg}`)
  ].join("\n");
}

async function runPackageCommand(cwd: string, args: string[]): Promise<void> {
  const subcommand = args[0] ?? "list";
  if (subcommand === "list") {
    console.log(formatPackageList(await listConfiguredPiPackages(cwd)));
    return;
  }

  if (subcommand === "recommended" || subcommand === "recommend") {
    console.log(recommendedPiPackagesMarkdown());
    return;
  }

  if (subcommand === "add") {
    const source = args.slice(1).join(" ").trim();
    if (!source) throw commandUsage("package add", "keating package add npm:pi-subagents");
    const packages = await addConfiguredPiPackage(cwd, source);
    console.log(`${color.ok}Added ${source} to ${relative(cwd, configPath(cwd))}.${color.reset}`);
    console.log(formatPackageList(packages));
    console.log(`${color.sepia}Packages sync into Pi settings the next time you run keating shell.${color.reset}`);
    return;
  }

  if (subcommand === "remove" || subcommand === "rm") {
    const source = args.slice(1).join(" ").trim();
    if (!source) throw commandUsage("package remove", "keating package remove npm:pi-subagents");
    const packages = await removeConfiguredPiPackage(cwd, source);
    console.log(`${color.ok}Removed ${source} from ${relative(cwd, configPath(cwd))}.${color.reset}`);
    console.log(formatPackageList(packages));
    return;
  }

  throw new Error([
    `Unknown package command: ${subcommand}`,
    "",
    "Recover with:",
    "  keating package list",
    "  keating package recommended",
    "  keating package add npm:pi-subagents",
    "  keating package remove npm:pi-subagents"
  ].join("\n"));
}

async function run(): Promise<void> {
  const rawArgs = process.argv.slice(2);
  const cwd = process.cwd();
  if (rawArgs.length === 1 && (rawArgs[0] === "--version" || rawArgs[0] === "-v" || rawArgs[0] === "version")) {
    console.log(`keating ${KEATING_VERSION}`);
    return;
  }
  const topLevelShellArgs = normalizeTopLevelShellArgs(rawArgs);
  if (topLevelShellArgs) {
    const exitCode = await launchShell(cwd, topLevelShellArgs);
    process.exitCode = exitCode;
    return;
  }

  const [command = "shell", ...args] = rawArgs;

  switch (command) {
    case "setup": {
      await setupProject(cwd, args);
      return;
    }
    case "package":
    case "packages": {
      await runPackageCommand(cwd, args);
      return;
    }
    case "web": {
      const { port, options } = parseWebCommand(args);
      await serveWeb(port, { ...options, projectRoot: options.projectRoot ?? cwd });
      return;
    }
    case "webmcp": {
      const portArg = firstPositional(args);
      const port = portArg ? parseInt(portArg, 10) : 3928;
      const host = optionValue(args, "--host") ?? "127.0.0.1";
      if (!Number.isInteger(port) || port < 1 || port > 65535) {
        throw new Error(`Invalid port: "${portArg}". Must be an integer between 1 and 65535.`);
      }
      const running = await serveWebMcp({ cwd, port, host });
      console.log(`${color.ok}${color.bold} Keating WebMCP ${color.reset}  ${color.parchment}${running.url}${color.reset}`);
      console.log(`${color.sepia}Connect MCP clients to the URL above. Press Ctrl+C to stop.${color.reset}`);
      return;
    }
    case "shell": {
      const exitCode = await launchShell(cwd, args);
      process.exitCode = exitCode;
      return;
    }
    case "plan": {
      const topic = args.join(" ").trim();
      if (!topic) throw commandUsage("plan", "keating plan derivative");
      const artifact = await planTopicArtifact(cwd, topic);
      console.log(relative(cwd, artifact.planPath));
      return;
    }
    case "map": {
      const topic = args.join(" ").trim();
      if (!topic) throw commandUsage("map", "keating map derivative");
      const artifact = await mapTopicArtifact(cwd, topic);
      console.log(relative(cwd, artifact.mmdPath));
      return;
    }
    case "animate": {
      const topic = args.join(" ").trim();
      if (!topic) throw commandUsage("animate", "keating animate derivative");
      const artifact = await animateTopicArtifact(cwd, topic);
      console.log(relative(cwd, artifact.playerPath));
      console.log(relative(cwd, artifact.scenePath));
      console.log(relative(cwd, artifact.storyboardPath));
      console.log(relative(cwd, artifact.manifestPath));
      return;
    }
    case "verify": {
      const topic = args.join(" ").trim();
      if (!topic) throw commandUsage("verify", "keating verify derivative");
      const result = await verifyTopicArtifact(cwd, topic);
      if (result.alreadyVerified) {
        console.log(`Already verified: ${relative(cwd, result.checklistPath)}`);
      } else {
        console.log(`Verification checklist: ${relative(cwd, result.checklistPath)}`);
      }
      return;
    }
    case "quiz": {
      const topic = args.join(" ").trim();
      if (!topic) throw commandUsage("quiz", "keating quiz derivative");
      const result = await quizTopicArtifact(cwd, topic);
      console.log(relative(cwd, result.quizPath));
      console.log(relative(cwd, result.answersPath));
      return;
    }
    case "bench": {
      const topic = args.join(" ").trim() || undefined;
      const result = await benchPolicyArtifact(cwd, topic);
      console.log(`${result.overallScore.toFixed(2)} ${relative(cwd, result.reportPath)}`);
      if (result.tracePath) console.log(relative(cwd, result.tracePath));
      return;
    }
    case "evolve": {
      const topic = args.join(" ").trim() || undefined;
      const result = await evolvePolicyArtifact(cwd, topic);
      console.log(`${result.bestScore.toFixed(2)} ${relative(cwd, result.reportPath)}`);
      if (result.tracePath) console.log(relative(cwd, result.tracePath));
      return;
    }
    case "prompt-evolve": {
      const promptName = args.join(" ").trim() || "learn";
      const result = await evolvePromptArtifact(cwd, promptName);
      console.log(`${result.bestScore.toFixed(2)} ${relative(cwd, result.reportPath)}`);
      console.log(relative(cwd, result.evolvedPromptPath));
      return;
    }
    case "prompt-eval": {
      const promptContent = args.join(" ").trim();
      if (!promptContent) throw commandUsage("prompt-eval", "keating prompt-eval \"Start with a diagnostic question.\"");
      const result = await promptEvalArtifact(cwd, promptContent);
      console.log(`${result.score.toFixed(2)} ${relative(cwd, result.reportPath)}`);
      return;
    }
    case "improve": {
      if (args[0] === "history") {
        const md = await improveHistory(cwd);
        console.log(md);
        return;
      }
      if (args[0] === "accept") {
        const proposalId = args[1];
        if (!proposalId) throw commandUsage("improve accept", "keating improve accept improve-abc123");
        const result = await improveAccept(cwd, proposalId);
        console.log(`${color.ok}Accepted ${proposalId}.${color.reset} After: ${result.afterScore.toFixed(2)} Delta: ${result.delta >= 0 ? "+" : ""}${result.delta.toFixed(2)}`);
        return;
      }
      if (args[0] === "reject") {
        const proposalId = args[1];
        if (!proposalId) throw commandUsage("improve reject", "keating improve reject improve-abc123");
        await improveReject(cwd, proposalId);
        console.log(`${color.ok}Rejected ${proposalId} and restored snapshots when available.${color.reset}`);
        return;
      }
      const artifact = await improveArtifact(cwd);
      console.log(`Proposal: ${artifact.proposal.id}`);
      console.log(`Targets: ${artifact.proposal.targets.map(t => t.file).join(", ")}`);
      console.log(relative(cwd, artifact.proposalPath));
      return;
    }
    case "auto-improve": {
      const force = args.includes("--force");
      const topic = args.filter((arg) => arg !== "--force").join(" ").trim() || undefined;
      const result = await autoImproveArtifact(cwd, topic, { force });
      const verdict = result.delta > 0
        ? `${color.ok}IMPROVED by +${result.delta.toFixed(2)}${color.reset}`
        : result.delta < -0.5
          ? `${color.err}REGRESSED by ${result.delta.toFixed(2)}${color.reset}`
          : `${color.sepia}NO SIGNIFICANT CHANGE (Δ${result.delta.toFixed(2)})${color.reset}`;
      console.log(`Baseline: ${result.baselineScore.toFixed(2)} → After: ${result.afterScore.toFixed(2)} — ${verdict}`);
      console.log(relative(cwd, result.reportPath));
      return;
    }
    case "edit": {
      await runEditCommand(cwd, args);
      return;
    }
    case "export": {
      await runExportCommand(cwd, args);
      return;
    }
    case "import": {
      await runImportCommand(cwd, args);
      return;
    }
    case "policy": {
      await ensureProjectScaffold(cwd);
      console.log(await currentPolicySummary(cwd));
      return;
    }
    case "trace": {
      await ensureProjectScaffold(cwd);
      const query = args.join(" ").trim().toLowerCase();
      const artifacts = await listArtifacts(cwd);
      for (const artifact of artifacts) {
        if (!query || artifact.path.toLowerCase().includes(query) || artifact.label.toLowerCase().includes(query)) {
          console.log(artifact.path);
        }
      }
      return;
    }
    case "learner-state": {
      await ensureProjectScaffold(cwd);
      const statePath = learnerStatePath(cwd);
      const state = await loadLearnerState(statePath);
      const upCount = state.feedback.filter((f) => f.signal === "thumbs-up").length;
      const downCount = state.feedback.filter((f) => f.signal === "thumbs-down").length;
      const confusedCount = state.feedback.filter((f) => f.signal === "confused").length;
      console.log(`${bold("primary", "Learner Profile")}`);
      console.log(`  Sessions: ${state.sessions?.length ?? 0}`);
      console.log(`  Topics covered: ${state.coveredTopics.length}`);
      for (const t of state.coveredTopics.slice(-10)) console.log(`    - ${t.slug} (${t.domain})`);
      const feedbackTopics = learnerFeedbackTopics(state);
      if (feedbackTopics.length > 0) {
        console.log(`  Feedback-only topics: ${feedbackTopics.length}`);
        for (const topic of feedbackTopics) console.log(`    - ${topic}`);
      }
      console.log(`  Feedback: 👍${upCount} 👎${downCount} 🤔${confusedCount}`);
      console.log(`  Misconceptions identified: ${state.identifiedMisconceptions.length}`);
      return;
    }
    case "timeline": {
      const { markdown } = await timelineArtifact(cwd);
      console.log(markdown);
      return;
    }
    case "due": {
      const { markdown } = await dueTopicsArtifact(cwd);
      console.log(markdown);
      return;
    }
    case "feedback": {
      await ensureProjectScaffold(cwd);
      const signalMap: Record<string, "thumbs-up" | "thumbs-down" | "confused"> = {
        up: "thumbs-up",
        down: "thumbs-down",
        confused: "confused"
      };
      const signal = signalMap[args[0]?.toLowerCase() ?? ""];
      if (!signal) {
        throw new Error([
          "feedback needs a signal: up, down, or confused.",
          "",
          "Recover with:",
          "  keating feedback up derivative",
          "  keating feedback confused derivative --comment=\"lost at chain rule\""
        ].join("\n"));
      }
      let comment: string | undefined;
      const filtered = args.filter((arg) => {
        if (arg.startsWith("--comment=")) {
          comment = arg.slice("--comment=".length);
          return false;
        }
        return true;
      });
      const topic = filtered.slice(1).join(" ") || "general";
      const statePath = learnerStatePath(cwd);
      const state = await loadLearnerState(statePath);
      recordFeedback(state, topic, signal, comment);
      await saveLearnerState(statePath, state);
      const sigLabel = { "thumbs-up": "👍 up", "thumbs-down": "👎 down", "confused": "🤔 confused" }[signal];
      const commentHint = comment ? ` (comment: "${comment}")` : "";
      console.log(`${color.ok}Recorded ${sigLabel} feedback for "${topic}"${commentHint}.${color.reset}`);
      return;
    }
    case "doctor": {
      await ensureProjectScaffold(cwd);
      const config = await loadKeatingConfig(cwd);
      const runtime = await detectAiRuntime(cwd);
      console.log(`${bold("primary", "Keating Doctor")}  ${color.sepia}diagnostic report${color.reset}\n`);
      console.log(`  ${color.cream}config_path${color.reset}           ${color.sepia}${configPath(cwd)}${color.reset}`);
      console.log(`  ${color.cream}ai_runtime_preference${color.reset} ${color.primary}${config.pi.runtimePreference}${color.reset}`);
      console.log(`  ${color.cream}ai_default_provider${color.reset}   ${config.pi.defaultProvider ?? color.sepia + "unset" + color.reset}`);
      console.log(`  ${color.cream}ai_default_model${color.reset}      ${config.pi.defaultModel ?? color.sepia + "unset" + color.reset}`);
      console.log(`  ${color.cream}ai_default_thinking${color.reset}   ${config.pi.defaultThinking ?? color.sepia + "unset" + color.reset}`);
      console.log(`  ${color.cream}debug_persist_traces${color.reset}  ${color.primary}${String(config.debug.persistTraces)}${color.reset}`);
      console.log(`  ${color.cream}debug_trace_top_learners${color.reset} ${color.primary}${String(config.debug.traceTopLearners)}${color.reset}`);
      console.log(`  ${color.cream}debug_console_summary${color.reset} ${color.primary}${String(config.debug.consoleSummary)}${color.reset}`);
      console.log(`  ${color.cream}ai_runtime${color.reset}            ${runtime.selected ? color.ok + runtime.selected.kind : color.err + "missing"}${color.reset}`);
      console.log(`  ${color.cream}ai_standalone${color.reset}         ${runtime.standalone ? color.primary + runtime.standalone.command : color.err + "missing"}${color.reset}`);
      console.log(`  ${color.cream}ai_embedded${color.reset}           ${runtime.embedded ? color.primary + (runtime.embedded.cliPath ?? runtime.embedded.command) : color.err + "missing"}${color.reset}`);
      if (runtime.selected) console.log(`  ${color.cream}ai_command${color.reset}            ${color.primary}${runtime.selected.command}${color.reset}`);
      console.log(`  ${color.cream}map_renderer${color.reset}          ${color.ok}mermaid-source${color.reset}`);
      console.log(`  ${color.cream}animation_renderer${color.reset}    ${color.ok}hyperframes${color.reset}`);
      return;
    }
    case "help":
    case "--help":
    case "-h": {
      printUsage();
      return;
    }
    default: {
      throw unknownCommand(command);
    }
  }
}

run().catch((error) => {
  console.error(`${color.err}${color.bold}Error:${color.reset} ${error instanceof Error ? error.message : String(error)}`);
  process.exitCode = 1;
});

